import { untrack } from 'svelte';
import { line as d3Line, lineRadial } from 'd3-shape';
import { geoPath as d3GeoPath } from 'd3-geo';
import { group as d3Group, max } from 'd3-array';
import { interpolatePath } from 'd3-interpolate-path';
import { accessor } from '../../utils/common.js';
import { isScaleBand } from '../../utils/scales.svelte.js';
import { createMotion, createPathMotionMap, extractTweenConfig, } from '../../utils/motion.svelte.js';
import { colorPropDataKey, resolveColorProp, resolveStyleProp } from '../../utils/dataProp.js';
import { getChartContext } from '../../contexts/chart.js';
import { getMarkData } from '../../contexts/facet.js';
import { getGeoContext } from '../../contexts/geo.js';
