                        stroke: group.style.stroke ?? lineStroke,
                        opacity: group.style.opacity ?? lineOpacity,
                        d: this.#buildPath(group.data),
                        data: group.data,
                        key: `${lineKey}\0${group.key}\0${ordinal}`,
